def table(rows,cols=None):
 rows=list(rows)
 if not rows:return '<p>Sin registros.</p>'
 cols=cols or list(rows[0]);return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(c)+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+('Faltante / no estimable' if r.get(c) is None else html.escape(str(round(r[c],4)) if isinstance(r.get(c),float) else str(r.get(c,''))))+'</td>' for c in cols)+'</tr>' for r in rows)+'</tbody></table></div>'

