 n=result['aceptadas_principal'];aux=result['aceptadas_corredor_auxiliar'];notgeo=sum(not a['OD_homologado'] for a in audit);wrong=sum(a['OD_homologado'] and not a['sentido_compatible'] for a in audit);arg=sum(a['alternativa_Argentina_compatible'] for a in audit);old22=sum(a['seleccionada_pantalla_anterior'] for a in audit)
